    Index_type i;
    real_t *x_ptr = x;
    real_t *y_ptr = y;

    // Set the vector length
    vl = vsetvl_e32m8(LEN_1D);

    // Initialize the vector load/store functions
    vfloat32m8_t vx, vy;
