    Index_type num_d = LTIMES_NUM_D, num_m = LTIMES_NUM_M;
    Index_type num_g = LTIMES_NUM_G, num_z = LTIMES_NUM_Z;

    // Use RISC-V Vector intrinsics to optimize the inner loop
    #if defined(__riscv_vector)
    Index_type vd = vsetvl_e32m8(num_d);
    vfloat32m8_t v_lt_elldat, v_lt_psidat, v_lt_phidat;
    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type z = 0; z < num_z; ++z)
        for (Index_type g = 0; g < num_g; ++g)
        for (Index_type m = 0; m < num_m; ++m) {
            v_lt_elldat = vle32_v_f32m8(lt_elldat + m * num_d, vd);
            v_lt_psidat = vle32_v_f32m8(lt_psidat + g * num_d + z * num_d * num_g, vd);
            v_lt_phidat = vle32_v_f32m8(lt_phidat + m + g * num_m + z * num_m * num_g, vd);
            v_lt_phidat = vfmacc_vv_f32m8(v_lt_phidat, v_lt_elldat, v_lt_psidat, vd);
            vse32_v_f32m8(lt_phidat + m + g * num_m + z * num_m * num_g, v_lt_phidat, vd);
        }
        dummy(lt_phidat, NULL, NULL, NULL, NULL, 0.0f);
    }
    #else
    // Use scalar code as a fallback when RISC-V Vector is not supported
    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type z = 0; z < num_z; ++z)
        for (Index_type g = 0; g < num_g; ++g)
        for (Index_type m = 0; m < num_m; ++m)
        for (Index_type dd = 0; dd < num_d; ++dd) {
            lt_phidat[m + g * num_m + z * num_m * num_g] +=
                lt_elldat[dd + m * num_d] *
                lt_psidat[dd + g * num_d + z * num_d * num_g];
        }
        dummy(lt_phidat, NULL, NULL, NULL, NULL, 0.0f);
    }
    #endif

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

