        vxx_ = __riscv_vmax_vv_i32m1(vxx_, vx, vl);
        vyn = __riscv_vmin_vv_i32m1(vyn, vy, vl);
        vyx = __riscv_vmax_vv_i32m1(vyx, vy, vl);
