        vse32_v_f32m8(x + i, vset1_v_f32m8(checksum, vl), vl);
    }
    #else
    // Use scalar code as a fallback
    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type i = 0; i < LEN_1D - 1; ++i) {
            x[i] = y[i+1] - y[i];
